const { execSync } = require('child_process');
const files = [
  '/data/workspace/banle/docs/FEATURES.md',
  '/data/workspace/banle/docs/PORTAL_NAVIGATION.md',
  '/data/workspace/banle/docs/REQUIREMENTS.md',
  '/data/workspace/banle/docs/USE_CASES.md',
  '/data/workspace/banle/docs/DATABASE_ARCHITECTURE.md'
];

let combinedContent = '';
for (const file of files) {
  try {
    // Tools return JSON strings like {"content": "..."}
    const rawResponse = execSync(`node /data/tools/fs/read_file.js ${file}`).toString();
    const parsed = JSON.parse(rawResponse);
    const content = parsed.content || parsed.error || 'Empty File';
    combinedContent += `\n\n--- FILE: ${file} ---\n${content}`;
  } catch (err) {
    combinedContent += `\n\n--- FILE: ${file} (ERROR) ---\n${err.message}`;
  }
}

return { combined_docs: combinedContent };

const { execSync } = require('child_process');
const responseText = $node["AI: Architect"].json.response; 

let taskMarkdown = '';
let summary = '';

try {
  // Attempt to parse AI response as JSON
  const cleanJsonStr = responseText.replace(/```json|```/g, '').trim();
  const data = JSON.parse(cleanJsonStr);

  summary = data.summary || 'Project Plan';

  if (data.tasks && Array.isArray(data.tasks)) {
    taskMarkdown = "# TASKS.md\n\n| ID | Role | Title | Description |\n|---|---|---|---|\n";
    data.tasks.forEach(t => {
       taskMarkdown += `| ${t.id} | ${t.role} | ${t.title} | ${t.description} |\n`;
    });
  } else {
    taskMarkdown = responseText; // Fallback to raw response
  }
} catch (e) {
  taskMarkdown = responseText; // Fallback to raw response
}

const base64Content = Buffer.from(taskMarkdown).toString('base64');
execSync(`node /data/tools/fs/write_file.js /data/workspace/banle/TASKS.md "${base64Content}" overwrite`);

return { status: 'success', path: '/data/workspace/banle/TASKS.md', summary };
